=head2 Google::Spanner::Admin::Instance::V1::SpannerInstanceAdmin::ListInstancesRequest

The request for
[ListInstances][google.spanner.admin.instance.v1.InstanceAdmin.ListInstances].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->parent() >> / C<< $msg->parent($value) >>

Type: C<String>

Required. The name of the project for which a list of instances is
requested. Values are of the form `projects/<project>`.

=item * C<< $msg->page_size() >> / C<< $msg->page_size($value) >>

Type: C<Int32>

Number of instances to be returned in the response. If 0 or less, defaults
to the server's maximum allowed page size.

=item * C<< $msg->page_token() >> / C<< $msg->page_token($value) >>

Type: C<String>

If non-empty, `page_token` should contain a
[next_page_token][google.spanner.admin.instance.v1.ListInstancesResponse.next_page_token]
from a previous
[ListInstancesResponse][google.spanner.admin.instance.v1.ListInstancesResponse].

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<String>

An expression for filtering the results of the request. Filter rules are
case insensitive. The fields eligible for filtering are:

  * `name`
  * `display_name`
  * `labels.key` where key is the name of a label

Some examples of using filters are:

  * `name:*` --> The instance has a name.
  * `name:Howl` --> The instance's name contains the string "howl".
  * `name:HOWL` --> Equivalent to above.
  * `NAME:howl` --> Equivalent to above.
  * `labels.env:*` --> The instance has the label "env".
  * `labels.env:dev` --> The instance has the label "env" and the value of
                       the label contains the string "dev".
  * `name:howl labels.env:dev` --> The instance's name contains "howl" and
                                 it has the label "env" with its value
                                 containing "dev".

=item * C<< $msg->instance_deadline() >> / C<< $msg->instance_deadline($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Deadline used while retrieving metadata for instances.
Instances whose metadata cannot be retrieved within this deadline will be
added to
[unreachable][google.spanner.admin.instance.v1.ListInstancesResponse.unreachable]
in
[ListInstancesResponse][google.spanner.admin.instance.v1.ListInstancesResponse].

=back

