=item * C<< $msg->expire_behavior() >> / C<< $msg->expire_behavior($value) >>

Type: C<Enum> (L<Google::Spanner::Admin::Instance::V1::FreeInstanceMetadata::ExpireBehavior>)

Specifies the expiration behavior of a free instance. The default of
ExpireBehavior is `REMOVE_AFTER_GRACE_PERIOD`. This can be modified during
or after creation, and before expiration.

=back

=head3 Enum: FreeInstanceMetadata::ExpireBehavior

=over 4

=item * C<EXPIRE_BEHAVIOR_UNSPECIFIED> => C<0>

=item * C<FREE_TO_PROVISIONED> => C<1>

=item * C<REMOVE_AFTER_GRACE_PERIOD> => C<2>

=back

